g.script:
{
   const CURL_RADIUS  = 10;
   const CURL_HEIGHT  =  5;
   const STROKE_WIDTH = +document.getElementById("page-entire").getAttribute("stroke-width");

   const STROKE_HW = STROKE_WIDTH / 2;

   const PAGE_X     = CURL_RADIUS + STROKE_HW;
   const PAGE_WIDTH = 100 - STROKE_HW - PAGE_X - CURL_RADIUS*2;

   {
      let node = document.getElementById("page-entire");
      let path = `
         M ${STROKE_HW} ${100 - STROKE_HW - CURL_RADIUS - CURL_HEIGHT}
         l ${CURL_RADIUS} 0
         L ${STROKE_HW + CURL_RADIUS} ${STROKE_HW + CURL_RADIUS}
         q ${0} ${-CURL_RADIUS}
           ${CURL_RADIUS} ${-CURL_RADIUS}
         L ${100 - STROKE_HW - CURL_RADIUS} ${STROKE_HW}
         q ${CURL_RADIUS} ${0}
           ${CURL_RADIUS} ${CURL_RADIUS}
         l 0 ${CURL_HEIGHT}
         l ${-CURL_RADIUS*2} 0
         L ${100 - STROKE_HW - CURL_RADIUS*2} ${100 - STROKE_HW - CURL_RADIUS}
         q ${0} ${CURL_RADIUS}
           ${-CURL_RADIUS} ${CURL_RADIUS}
         L ${STROKE_HW + CURL_RADIUS} ${100 - STROKE_HW}
         q ${-CURL_RADIUS} ${0}
           ${-CURL_RADIUS} ${-CURL_RADIUS}
         Z
      `;
      path = path.trim().replaceAll(/\s+/g, " ");
      node.setAttribute("d", path);
   }
   {
      let node = document.getElementById("page-inner-lines");
      let path = `
         M ${STROKE_HW} ${100 - STROKE_HW - CURL_RADIUS - CURL_HEIGHT}
         L ${100 - STROKE_HW - CURL_RADIUS*4} ${100 - STROKE_HW - CURL_RADIUS - CURL_HEIGHT}
         l 0 ${CURL_HEIGHT}
         q ${0} ${CURL_RADIUS}
           ${CURL_RADIUS} ${CURL_RADIUS}

         M ${100 - STROKE_HW - CURL_RADIUS} ${STROKE_HW}
         q ${-CURL_RADIUS} ${0}
           ${-CURL_RADIUS} ${CURL_RADIUS}
         l 0 ${CURL_HEIGHT}
         l ${CURL_RADIUS*2} 0
      `;
      path = path.trim().replaceAll(/\s+/g, " ");
      node.setAttribute("d", path);
   }
}
